const memo = new Map<number, bigint>()
const fibBig = (n: number): bigint => {
    if (n < 2) return BigInt(n)
    if (!memo.has(n)) memo.set(n, fibBig(n - 1) + fibBig(n - 2))
    return memo.get(n)!
}
console.log(fibBig(90).toString(), "| keshdagi qiymatlar:", memo.size)

