const ttlCache = new Map<string, { value: string; exp: number }>()
let now = 0
const put = (k: string, v: string, ttl: number) => ttlCache.set(k, { value: v, exp: now + ttl })
const read = (k: string) => { const e = ttlCache.get(k); if (!e || e.exp <= now) { ttlCache.delete(k); return undefined } return e.value }
put("token", "abc", 100)
console.log(read("token")); now = 150; console.log(read("token"), ttlCache.size)

