const partition = <T,>(arr: T[], pred: (x: T) => boolean): [T[], T[]] => arr.reduce<[T[], T[]]>(([yes, no], x) => (pred(x) ? [[...yes, x], no] : [yes, [...no, x]]), [[], []])
const [adults, minors] = partition([12, 25, 17, 40], age => age >= 18)
